def _folded(text):
    """The reading a match ignores case and stray spacing against."""
    return ' '.join((text or '').strip().lower().split())


# The spellings the ledger keeps for the church budget account, whatever
# wording arrived on the row. Each names the account whose short name is
# 'LCB' or whose description is the budget's full name.
LCB_FAMILY = {'lcb', 'local church budget', 'local church budget (lcb)'}


